export function createHttpClient(options = {}) {
  const timeout = Number(options.timeout ?? 5000);
  if (!Number.isFinite(timeout) || timeout <= 0) {
    throw new RangeError('timeout must be positive');
  }
  const baseUrl = String(options.baseUrl ?? '').replace(/\/$/, '');

  return Object.freeze({
    async get(path, init = {}) {
      const res = await fetch(`${baseUrl}${path}`, {
        ...init,
        signal: AbortSignal.timeout(timeout)
      });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      return res.json();
    }
  });
}

class UserBuilder {
  #data = { role: 'member', active: true };
  withId(id) { this.#data.id = id; return this; }
  asAdmin() { this.#data.role = 'admin'; return this; }
  inactive() { this.#data.active = false; return this; }
  build() {
    if (!this.#data.id) throw new Error('id required');
    return structuredClone(this.#data);
  }
}

const admin = new UserBuilder().withId('u1').asAdmin().build();

public sealed class HttpClientWrapper
{
    private readonly HttpClient _client;
    public HttpClientWrapper(HttpClient client, Uri baseUrl, TimeSpan timeout)
    {
        _client = client;
        _client.BaseAddress = baseUrl;
        _client.Timeout = timeout;
    }
}

